export type CardKind = 'kanji' | 'vocab';
export type CardStatus = 'locked' | 'new' | 'learning' | 'review' | 'mastered';

// --- static data (web/public/data, generated by scripts/build-data.ts) -------

export type KanjiItem = {
  char: string;
  jlpt: number;
  strokes: number | null;
  grade: number | null;
  freq: number | null;
  meanings: string[];
  on: string[];
  kun: string[];
  parts: Part[];
  phon?: string; // the component that hints at the on'yomi (飯 → 反), from KanjiVG
  status?: CardStatus;
};

// A visible component of a kanji. r: it's the kanji's radical; p: it carries the sound;
// n: how many times it appears (林 = 木 ×2).
export type Part = { c: string; r?: 1; p?: 1; n?: number };

// Meaning and on'yomi of a component that isn't itself a JLPT kanji (氵, 昜).
export type Component = { m: string; on: string[] };

export type VocabItem = {
  id: string; // "word|reading": stable across data rebuilds, so progress stays attached
  word: string;
  alt: string[];
  readings: string[];
  meaning: string;
  jlpt: number | null;
  source: 'jlpt' | 'jmdict';
  status?: CardStatus;
};

export type DataFile = { builtAt: string; kanji: KanjiItem[]; vocab: VocabItem[]; components: Record<string, Component> };

// An example sentence for a word, from Tatoeba: Japanese, English, and the word as it
// appears in the sentence (inflected: 行った for 行く), for highlighting.
export type Sentence = { j: string; e: string; w: string };

// KanjiVG stroke paths in drawing order (109×109 viewBox), plus stroke-number label positions.
export type StrokeData = { d: string[]; n: [number, number][] };

// --- progress: an append-only event log; card state is a replay of it --------

type EventBase = { id: string; ts: number };
export type StudyEvent =
  | (EventBase & { type: 'learn'; key: string })
  | (EventBase & { type: 'review'; key: string; rating: 1 | 2 | 3 | 4; answer?: string; ms?: number })
  | (EventBase & { type: 'settings'; settings: Partial<Settings> })
  // Memory stories: a recurring character for each part, and a scene for each kanji.
  // The latest edit wins; an empty name or text clears it.
  | (EventBase & { type: 'actor'; part: string; name: string; desc?: string })
  | (EventBase & { type: 'story'; char: string; text: string });

export type Actor = { name: string; desc?: string };

export type ExportFile = { app: 'kanji'; version: 1; exportedAt: string; events: StudyEvent[] };

// --- view models -------------------------------------------------------------

export type PartDetail = Part & { meaning: string; kanji: boolean; actor?: Actor };

// Kanji sharing a sound part. `shares`: has an on'yomi in common with the kanji being viewed
// (ignoring dakuten, so 板 バン matches 反 ハン).
export type SoundMember = Pick<KanjiItem, 'char' | 'on' | 'status'> & { meaning: string; shares: boolean };
export type SoundFamily = {
  char: string; on: string[]; meaning: string; kanji: boolean;
  shared: string[]; // this kanji's on'yomi that the sound part or its family also have
  members: SoundMember[];
};

export type KanjiDetail = KanjiItem & {
  vocab: VocabItem[];
  partList: PartDetail[];
  sound: SoundFamily | null;
  story?: string;
  self?: Actor; // this kanji's own character, when it's a part in other kanji
  usedIn: string[]; // JLPT kanji that contain this one as a part
  misses: number; // times answered Again
};

// One entry on the Cast page: a part, its character, and the kanji it appears in.
export type CastEntry = { part: string; meaning: string; kanji: boolean; actor?: Actor; usedIn: string[]; learned: number };
export type VocabDetail = VocabItem & { kanji: Pick<KanjiItem, 'char' | 'meanings'>[] };

export type Lesson =
  | { kind: 'kanji'; item: KanjiDetail }
  | { kind: 'vocab'; item: VocabDetail };

// Human-readable next interval for each rating, e.g. { 1: '1m', 2: '6m', 3: '10m', 4: '5d' }.
export type IntervalPreview = Record<1 | 2 | 3 | 4, string>;

export type Review = Lesson & { key: string; intervals: IntervalPreview };

export type Summary = {
  due: number;
  nextDue: number | null; // epoch ms of the next card coming due, if none due now
  lessons: number;
  today: { kanji: number; vocab: number; reviews: number; correct: number };
  levels: { jlpt: number; total: number; started: number; mastered: number }[];
  vocab: { total: number; started: number; mastered: number };
};

export type Settings = {
  kanjiPerDay: number;
  vocabPerDay: number;
  retention: number; // FSRS desired retention, 0.7–0.97
  kanjiPrompt: 'meaning' | 'reading'; // what kanji review cards ask for; words always ask the reading
};

export type KanjiListItem = Pick<KanjiItem, 'char' | 'jlpt' | 'status'> & { meaning: string };
